from nltk.corpus import wordnet as wn

def get_lcs(word1, word2):
    s1 = wn.synsets(word1)[0]
    s2 = wn.synsets(word2)[0]
    root = s1.lowest_common_hypernyms(s2)
    return root[0].name()

from nltk.tokenize import word_tokenize

def lexical_diversity(text):
    tokens = word_tokenize(text.lower())
    return len(set(tokens)) / len(tokens)

def file_stats(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        text = f.read()
    words = text.split()
    return len(text), len(words), len(set(words))

def safe_decode(byte_stream):
    try:
        return byte_stream.decode('utf-8')
    except UnicodeDecodeError:
        return byte_stream.decode('utf-8', errors='replace')

import unicodedata
def count_unicode_categories(text):
    normalized = unicodedata.normalize('NFC', text)
    return {char: unicodedata.category(char) for char in normalized}

import nltk
def count_verbs(text):
    tokens = nltk.word_tokenize(text)
    tags = nltk.pos_tag(tokens)
    return sum(1 for word, tag in tags if tag.startswith('VB'))

