class SimpleLookupTagger:
    def __init__(self, mapping, fallback='NN'):
        self.mapping = mapping
        self.fallback = fallback
    def tag(self, tokens):
        return [(t, self.mapping.get(t, self.fallback)) for t in tokens]

def evaluate(gold, pred):
    correct = sum(g == p for (_, g), (_, p) in zip(gold, pred))
    return correct / len(gold)

def evaluate_baseline(gold_corpus, baseline_tagger):
    correct = total = 0
    for sent in gold_corpus:
        words, gold_tags = zip(*sent)
        pred_tags = [tag for word, tag in baseline_tagger.tag(words)]
        for p, g in zip(pred_tags, gold_tags):
            if p == g: correct += 1
            total += 1
    return correct / total

